# Numeric and list builtins lowered to runtime calls (pycc_hir::builtins).
print(int("42") + 1, int(" -7\n"), int("1_000"), int("+5"), int("ff", 16), int("0x1f", 0), int("101", 2))
print(int(3.9), int(-3.9), int(True), int(7), int("123456789012345678901234567890"))
print(int(1e20), int(-2.5e18))
print(float("1.5"), float(" -2 "), float("inf"), float("-Infinity"), float("1e3"), float("1_0.5"))
print(abs(-5), abs(5), abs(-2.5), abs(False), bin(10), bin(-5), bin(0), hex(255), oct(8))
print(min(3, 1, 2), max(3, 1, 2), min(2, 2), max(1.5, 0.5), max(True, False), min(True, 0))
print(pow(3, 200, 1000000007), pow(2, -1, 7), pow(5, 3, -7), pow(0, 0, 3))
ys = [5, 3, 9, 1, 3]
print(min(ys), max(ys), sum(ys), sorted(ys), ys)
ys.sort()
print(ys)
ys.reverse()
print(ys, ys.count(3), ys.index(9))
ys.remove(3)
print(ys, list(ys), ys.copy(), list(reversed(ys)))
zs = ys.copy()
zs.clear()
print(zs, ys)
fs = [2.5, -1.0, 3.25]
print(min(fs), max(fs), sum(fs), sorted(fs), sum([0.1] * 10), sum([1e16, 1.0, -1e16]))
print(sum([True, True, False]), any([0, 0, 1]), all([1, 2, 0]))
print(any(["", "a"]), all([1.0, 0.0]))
print(1e16, 1.5e-5, 123456789012345678.0, -2.5e-10, 1e300 * 10, 0.0001)
print(int("abc"))
